class BlueLabel(QLabel):
    def __init__(self, text="", parent=None):
        super().__init__(parent)
        self._text = text
        self._rect_color = QColor("#2A87DB")

    def setText(self, text):
        self._text = text
        self.update()
    def paintEvent(self, event):
        super().paintEvent(event)
        painter = QPainter(self)
        # 绘制蓝色矩形
        rect_width = 22  # 矩形宽度
        rect_height = 20  # 矩形高度与 QLabel 高度一致
        painter.fillRect(0, 0, 16, rect_height, QColor("#F6F9FF"))
        painter.fillRect(16, 0, rect_width - 16, rect_height, self._rect_color)

        # 绘制文本
        text_rect = self.rect()  # 获取 QLabel 的矩形区域
        text_rect.adjust(rect_width + 5, 0, 0, 0)  # 调整文本绘制区域，留出矩形的空间
        painter.setPen(Qt.black)  # 设置文本颜色为黑色
        painter.drawText(text_rect, Qt.AlignLeft | Qt.AlignVCenter, self._text)

