    def open_data_tran(self):
        try:
            options = QFileDialog.Options()
            path = QFileDialog.getExistingDirectory(None, "Select Directory", options=options)
            if path:
                from .process_path import process_path
                QLLogging.log.debug("enter process_path")
                process_path(path)
                QLLogging.log.debug("process_path successfully")
                last_foler_name = os.path.basename(path)
                edf_path = os.path.join(path, f"{last_foler_name}.edf")
                QLLogging.log.debug("enter showInfo")
                self.showInfo(edf_path)
                QLLogging.log.debug("showInfo successfully")

                base_path = os.path.dirname(edf_path)
                result_path = os.path.join(base_path, 'Result')
                from datetime import datetime
                folder_name = datetime.now().strftime('%Y%m%d_%H%M%S')
                folder_path = os.path.join(result_path, folder_name)
                # os.makedirs(result_path, exist_ok=True)
                # os.makedirs(folder_path, exist_ok=True)
                self.updateDescription(folder_path)
        except Exception as e:
            QLLogging.log.exception(f"open_data_tran error: {e}")

    # edf/bdf文件路径
    def open_data_import(self):
        if self.is_not_first_open:
            try:
                # 弹一个弹窗告诉用户是否需要关闭文件
                msg_box = QMessageBox(self)
                msg_box.setFixedSize(500, 300)
                # 设置一下背景颜色
                msg_box.setStyleSheet(ControlStyle.get_widget_style())
                # 设置消息类型为信息类型
                msg_box.setIcon(QMessageBox.Information)
                msg_box.setWindowTitle("提示")  # 设置弹窗标题
                msg_box.setText("打开新的文件会关闭当前所有正在运行的分析窗口，确定打开新文件？")  # 设置弹窗内容
                # 添加自定义按钮
                # 这里“确认并打开”设为 AcceptRole，“取消”设为 RejectRole
                btn_confirm_open = msg_box.addButton("确认并打开", QMessageBox.AcceptRole)
                btn_confirm_open.setFixedSize(120, 32)
                btn_confirm_open.setStyleSheet(ControlStyle.get_pushButton_style())
                btn_cancel = msg_box.addButton("取消", QMessageBox.RejectRole)
                btn_cancel.setFixedSize(120, 32)
                btn_cancel.setStyleSheet(ControlStyle.get_pushButton_style_white())

                # 显示弹窗并获取点击的按钮
                clicked_btn = msg_box.exec_()

                if clicked_btn == msg_box.buttonRole(btn_cancel):
                    QLLogging.log.debug("点击了取消")
                    return

            except Exception as e:
                QLLogging.log.exception(f"is_not_first_open error: {e}")

        # 先调用 close
        self.close_file()

        self.is_not_first_open = True # 修改标志
        QLLogging.log.debug("enter browse_files")
        self.browse_files()
        QLLogging.log.debug("browse_files successfully")

    def browse_files(self):
        try:
            from PyQt5.QtCore import QSettings
            self.settings = QSettings("QUANLAN", "AR_analyser")
            self.last_opened_path = self.settings.value("lastOpenedPath", "")

            options = QFileDialog.Options()
            file_filter = 'EDF and BDF Files (*.edf *.bdf)'
            file_name, _ = QFileDialog.getOpenFileName(None, "Select EDF or BDF File", self.last_opened_path, options=options, filter=file_filter)

            if file_name:
                # 弹出“请等待”消息框
                wait_box = QMessageBox(QMessageBox.Information, "请稍等", "正在打开文件，请勿关闭窗口...", parent=self)
                wait_box.setStyleSheet(ControlStyle.get_widget_style())
                # wait_box.setStandardButtons(QtWidgets.QMessageBox.NoButton)
                # 设置标准按钮为Ok，然后将其文本设置为空
                wait_box.setStandardButtons(QtWidgets.QMessageBox.Ok)
                # 获取Ok按钮
                ok_button = wait_box.button(QtWidgets.QMessageBox.Ok)
                if ok_button:
                    ok_button.setText("")  # 设置为空字符串

                # 隐藏关闭按钮
                wait_box.setWindowFlags(Qt.Dialog | Qt.CustomizeWindowHint |
                                   Qt.WindowTitleHint)

                wait_box.show()
                # 刷新 GUI
                QApplication.processEvents()

                self.show_file_widget.show()
                self.show_file_ScrollArea.show()
                self.file_path = file_name
                self.show_file_widget.show_file_label.setText(self._split_file_path(self.file_path))
                self.settings.setValue("lastOpenedPath", os.path.dirname(file_name))
                self.process_path()
                OPLog.write(SQLLiteDB_Only_MainTread.user_db, OPType.BASIC.value, 'browse files', 0)

                wait_box.close()

            else:
                self.is_not_first_open = False

        except Exception as e:
            QLLogging.log.exception(f"browse_files error: {e}")

    def process_path(self):
        if self.file_path.endswith('.edf') or self.file_path.endswith('.bdf'):
            try:
                self.showInfo(self.file_path)

                base_path = os.path.dirname(self.file_path)
                result_path = os.path.join(base_path, 'Result')
                from datetime import datetime
                folder_name = datetime.now().strftime('%Y%m%d_%H%M%S')
                folder_path = os.path.join(result_path, folder_name)
                # os.makedirs(result_path, exist_ok=True)
                # os.makedirs(folder_path, exist_ok=True)
                self.updateDescription(folder_path)
                QLLogging.log.info(f"process file {self.file_path} successfully")
            except Exception as e:
                QLLogging.log.exception(f"Failed to load the file: {e}")
        else:
            QMessageBox.critical(None, "File Error",
                                 "The selected file is not a .edf file. Please select a valid .edf file.")

    def open_basical_analysis_ui(self):
        try:
            if self.raw_processed is None:
                QtWidgets.QMessageBox.warning(None, "Error", "Please load data file first.")
                return
            from .BasicalAnalysis import Ui_xxx_analysis
            self.basical_window = QtWidgets.QWidget()
            self.basical_ui = Ui_xxx_analysis()
            self.basical_ui.import_raw(self.raw_processed)
            self.basical_ui.setupUi(self.basical_window)
            self.basical_ui.detect_length(self.raw_processed)
            self.basical_window.show()
        except Exception as e:
            QLLogging.log.exception(f"Failed to open the basical window: {e}")

    def open_filter_ui(self):
        if self.raw_processed is None:
            QtWidgets.QMessageBox.warning(None, "Error", "Please load data file first.")
            # QLLogging.log.exception("Error, Please load data file first.")
            return
        from .Filter import Ui_Filter
        if self.filter_window is None:
            self.filter_window = QtWidgets.QWidget()
            self.filter_ui = Ui_Filter()
            self.filter_ui.setupUi(self.filter_window)
            self.filter_ui.showChannel(self.raw_processed)
            # 这里进行文件名字的添加
            # self.filter_ui.label.setText(self._split_file_path(self.file_path))
            self.filter_ui.signal_sender.filter_applied.connect(self.updateRawObject)

        if self.filter_window.isMinimized():
            # 如果窗口处于最小化状态，恢复窗口
            self.filter_window.setWindowState(self.filter_window.windowState() & ~Qt.WindowMinimized | Qt.WindowActive)

        self.filter_window.show()
        self.filter_window.raise_()

    def open_recommanded_ui(self):
        from .Recommended import Ui_Recommended
