    def showInfo(self, file_path):
        try:
            # self.textEdit.show()  # 这个页面是一个TextEdit
            self.welcome_widget.welcome_text0.hide()
            self.welcome_widget.welcome_widget_old.hide()
            self.welcome_widget.welcome_text1.hide()
            self.showFileWidgetShow()
            self.show_file_ScrollArea.show()

            file_extension = os.path.splitext(file_path)[1].lower()
            QLLogging.log.debug("enter EdfReader")
            edf_r = EdfReader(file_path)
            QLLogging.log.debug("EdfReader successfully")
            start_time = edf_r.getStartdatetime()
            del edf_r

            if file_extension == '.edf':
                QLLogging.log.debug("enter mne.io.read_raw_edf")
                self.raw = mne.io.read_raw_edf(file_path, preload=True, verbose=False)
                QLLogging.log.debug("mne.io.read_raw_edf successfully")
                # self.raw._data = self.raw.get_data().astype('float32') # 将数据转换为float32类型

            elif file_extension == '.bdf':
                QLLogging.log.debug("enter mne.io.read_raw_bdf")
                self.raw = mne.io.read_raw_bdf(file_path, preload=True, verbose=False)
                QLLogging.log.debug("mne.io.read_raw_bdf successfully")

            # 直接将数据转换为微伏（而不是先存储在中间变量中）
            self.raw._data *= 1e6  # 将数据转换为微伏，直接修改self.raw._data

            # 如果你只想保留最终处理后的数据，创建一个新的 RawArray 对象
            QLLogging.log.debug("enter mne.io.RawArray")
            self.raw_processed = mne.io.RawArray(self.raw._data, self.raw.info)
            QLLogging.log.debug("mne.io.RawArray successfully")

            ControlStyle._textEdit_word_style(self.show_file_widget.show_file_infotext)
            ControlStyle._textEdit_word_style(self.show_file_widget.show_file_disposetext1)
            ControlStyle._textEdit_word_style(self.show_file_widget.show_file_disposetext2)
            ControlStyle._textEdit_word_style(self.show_file_widget.show_file_disposetext3)

            n_channels = len(self.raw_processed.ch_names)
            n_times = self.raw_processed.n_times
            sfreq = self.raw_processed.info['sfreq']
            total_duration = n_times / sfreq
            hms = self.seconds_to_hms(total_duration)

            data = self.raw_processed.get_data()
            memory_usage_mb = data.size * data.itemsize / (1024 ** 2)
            memory_usage_mb = round(memory_usage_mb, 2)

            test1 = "数据规格：          " + str(n_channels) + "x" + str(n_times)
            test2 = "数据时长：          " + hms
            test3 = "数据大小：          " + str(memory_usage_mb) + "MB"
            test4 = "通道数量：          " + str(n_channels)

            # 添加内容到textEdit中的内容
            ch_name = self.raw_processed.info['ch_names']
            sfreq = self.raw_processed.info['sfreq']
            meas_date = self.raw_processed.info['meas_date']
            try:
                new_ch_name = []

                change_ch_name = False

                for ch in ch_name:
                    if ch in self.ch_name_mapping:
                        change_ch_name = True
                        new_ch_name.append(self.ch_name_mapping[ch])
                # 需要有一个条件
                if change_ch_name:
                    ch_name = new_ch_name

                    # 假设 self.raw_processed 是 MNE 的 Raw 对象，ch_name 是新通道名称列表
                    # 构建原通道名和新通道名的映射字典
                    name_mapping = {old_name: new_name for old_name, new_name in zip(self.raw_processed.ch_names, ch_name)}
                    # 执行重命名
                    self.raw_processed.rename_channels(name_mapping)
            except Exception as e:
                print(e)
                QLLogging.log.exception(f"{e}")

            test5 = "通道名称：          " + str(ch_name)
            test6 = "采样率：            " + str(sfreq) + "Hz"
            test7 = "文件路径：          " + str(file_path)
            test8 = "记录开始时间：   " + str(meas_date) + " UTC"

            self.show_file_widget.show_file_infotext.append(test1)
            self.show_file_widget.show_file_infotext.append(test2)
            self.show_file_widget.show_file_infotext.append(test3)
            self.show_file_widget.show_file_infotext.append(test4)
            self.show_file_widget.show_file_infotext.append(test5)
            self.show_file_widget.show_file_infotext.append(test6)
            self.show_file_widget.show_file_infotext.append(test7)
            self.show_file_widget.show_file_infotext.append(test8)

            self.show_file_widget.show_file_disposetext1.append("【Filter】")
            self.show_file_widget.show_file_disposetext1.append("# Filter(EEG0):   None")
            self.show_file_widget.show_file_disposetext1.append("# Filter(EEG1):   None")
            self.show_file_widget.show_file_disposetext1.append("# Filter(EEG2):   None")
            self.show_file_widget.show_file_disposetext1.append("# Filter(EEG3):   None")
            self.show_file_widget.show_file_disposetext1.append("# Filter(ACC0):   None")
            self.show_file_widget.show_file_disposetext1.append("# Filter(ACC1):   None")
            self.show_file_widget.show_file_disposetext1.append("# Filter(ACC2):   None")

            self.show_file_widget.show_file_disposetext2.append("【data selection】")
            self.show_file_widget.show_file_disposetext2.append("暂无")
            self.show_file_widget.show_file_disposetext3.append("【preview and rejection】")
            self.show_file_widget.show_file_disposetext3.append("暂无")

            self.raw_ch_names = self.raw_processed.ch_names
            self.raw_sfreq = self.raw_processed.info["sfreq"]
            self.raw_data = self.raw_processed._data

            # 删除不再需要的原始数据
            del self.raw

            # 成功加载数据后启用菜单和关闭
            self.menuPreprocess.setEnabled(True)
            self.menuAnalysis_module.setEnabled(True)
            self.action_close_file.setEnabled(True)
            self.action_save_file.setEnabled(True)

        except Exception as e:
            self.welcome_widget.welcome_text0.show()
            self.welcome_widget.welcome_widget_old.show()
            self.welcome_widget.welcome_text1.show()
            self.show_file_ScrollArea.hide()
            self.showFileWidgetHide()
            # 创建一个显示错误的弹窗
            msg_box = QMessageBox()
            msg_box.setIcon(QMessageBox.Critical) # 设置图标为错误图标
            msg_box.setWindowTitle("错误提示")
            msg_box.setText(f"<p style='font-size: 25px;'>Failed to load the file:\n</p> <div>{e}</div>")
            # msg_box.setText("<p style='font-size: 25px;>Failed to load the file:</p>")
            # msg_box.setInformativeText(f"{e}")
            msg_box.exec_()
            QLLogging.log.exception(f"Failed to load the file: {e}")
            # 加载失败时确保菜单保持禁用
            self.menuPreprocess.setEnabled(False)
            self.menuAnalysis_module.setEnabled(False)
            raise e

    def seconds_to_hms(self, seconds):
        # 计算小时数
        hours = int(seconds // 3600)
        # 计算剩余的秒数用于计算分钟数
        remaining_seconds = seconds % 3600
        # 计算分钟数
        minutes = int(remaining_seconds // 60)
        # 计算最后的秒数
        secs = int(remaining_seconds % 60)
        # 格式化输出为 HH:MM:SS 格式
        return f"{hours:02d}:{minutes:02d}:{secs:02d}"

    def updateDescription(self, folder_path):
        self.raw_processed.info['description'] = folder_path

    def updateRawObject(self, raw=None, reject_log=None):
        """更新Raw对象和显示信息"""
        self.raw_processed = raw
        # 准备显示文本
        if raw is None:
            info_text = "Raw Object: None\n"
            if reject_log:
                info_text += reject_log
            else:
                info_text += "\nAll data has been rejected."
                QLLogging.log.exception("All data has been rejected. raw is None\n")
            QLLogging.log.exception("Raw Object: None\n")
        else:
            info_text = f"Raw Object:\n{self.raw_processed}\n\nRaw Info:\n{self.raw_processed.info}"
            if reject_log:
                info_text += reject_log
                QLLogging.log.debug("reject_log exist\n")

        try:
            # 需要进行分情况讨论，因为不同的按钮获取的reject_log是不一样的
            if hasattr(self, "filter_ui") and self.filter_ui is not None:
                self.filter_ui.pushButton_2_signals.pushButton_2_signal.connect(
                    lambda: self.get_filter_UI_reject_log(reject_log))

            if hasattr(self, "select_ui") and self.select_ui is not None:
                self.select_ui.apply_pushButton_signals.apply_pushButton_signal.connect(
                    lambda: self.get_select_UI_reject_log(reject_log))

            if hasattr(self, "reject_ui") and self.reject_ui is not None:
                self.reject_ui.apply_pushButton_signals.apply_pushButton_signal.connect(
                    lambda: self.get_reject_UI_reject_log(reject_log))
        except Exception as e:
            QLLogging.log.exception(f"Write data to the top page, an error occurs: {str(e)}") # 428

        # 更新菜单状态
        has_data = raw is not None
        self.menuPreprocess.setEnabled(has_data)
        self.menuAnalysis_module.setEnabled(has_data)
        self.action_close_file.setEnabled(has_data)
        self.action_save_file.setEnabled(has_data)

    def get_filter_UI_reject_log(self, reject_log):
        try:
            print("get_filter_UI_reject_log")
            pattern = r':\s*(.*)'
            results = re.findall(pattern, reject_log)
            results[0] = results[0].split(':')[-1].strip()
            self.show_file_widget.show_file_disposetext1.clear()
            ControlStyle._textEdit_word_style(self.show_file_widget.show_file_disposetext1)
            self.show_file_widget.show_file_disposetext1.append("【Filter】")

            QLLogging.log.debug(f"len(results):{len(results)}")

            # 先将历史数据添加到history中
            for i in range(len(results)):
                test = results[i]
                if test not in self.history_filter_log[i] and test != "None":
                    self.history_filter_log[i].append(test)

            if results is not None:
                for i in range(len(self.history_filter_log)):
                    if i < 4:
                        self.show_file_widget.show_file_disposetext1.append(f"# Filter(EEG{i}):   " + "  ".join(self.history_filter_log[i]))
                    else:
                        self.show_file_widget.show_file_disposetext1.append(f"# Filter(ACC{i - 4}):   " + "  ".join(self.history_filter_log[i]))
        except Exception as e:
            QLLogging.log.exception(f"get_filter_UI_reject_log error: {str(e)}") # 428
    def get_select_UI_reject_log(self, reject_log):
        try:
            pattern = r':\s*(.*)'
            results = re.findall(pattern, reject_log)
            if results is not None:
                test = results[0].replace("start time: ", "")
                self.show_file_widget.show_file_disposetext2.clear()
                ControlStyle._textEdit_word_style(self.show_file_widget.show_file_disposetext2)
                self.show_file_widget.show_file_disposetext2.append("【data selection】")
                self.show_file_widget.show_file_disposetext2.append(test + " -- " + results[1])
        except Exception as e:
            QLLogging.log.exception(f"get_select_UI_reject_log error: {str(e)}") # 428

    def get_reject_UI_reject_log(self, reject_log):
        try:
            # 定义正则表达式模式
            # pattern = r'\d{2}:\d{2}:\d{2} - \d{2}:\d{2}:\d{2}'
            # results = re.findall(pattern, reject_log)
            self.show_file_widget.show_file_disposetext3.clear()
            self.show_file_widget.show_file_disposetext3.append("【preview and rejection】")
            ControlStyle._textEdit_word_style(self.show_file_widget.show_file_disposetext3)

            if self.reject_ui.history_reject_time is not None:
                # 先合并数组
                self.history_reject_time.extend(self.reject_ui.history_reject_time)
                # 再进行判断数量是否大于100，如果大于100，头删至100
                while len(self.history_reject_time) > 100:
                    self.history_reject_time.popleft()  # 使用deque的popleft替代列表的pop(0)

                for i in range(len(self.history_reject_time)):
                    number = i + 1
                    print(f"self.reject_ui.history_reject_time[i]:{self.history_reject_time[i]}")
                    self.show_file_widget.show_file_disposetext3.append(f"reject{number:2d}:  " + self.history_reject_time[i])
        except Exception as e:
            QLLogging.log.exception(f"get_reject_UI_reject_log error: {str(e)}") # 428

