    def open_qlass_analysis(self):
        if self.raw_processed is None:
            QLLogging.log.exception("Error! Please load data file first.")
            QtWidgets.QMessageBox.warning(None, "Error", "Please load data file first.")
            return

        try:
            from .QlassAnalysis import Ui_qlass_analysis
            if self.qlass_window is None:
                self.qlass_window = QtWidgets.QWidget()
                self.qlass_ui = Ui_qlass_analysis(self.qlass_window)
                self.qlass_ui.import_raw(self.raw_processed)
                self.qlass_ui.setupUi(self.qlass_window)

                self.qlass_ui.file_name = self._split_file_path(self.file_path)

                # # 连接窗口关闭信号 - 使用正确的方法绑定
                self.qlass_window.closeEvent = self.create_close_handler()
            if self.qlass_window.isMinimized():
                # 如果窗口处于最小化状态，恢复窗口
                self.qlass_window.setWindowState(self.qlass_window.windowState() & ~Qt.WindowMinimized | Qt.WindowActive)

            self.qlass_window.showMaximized()
            self.qlass_window.raise_()
            OPLog.write(SQLLiteDB_Only_MainTread.user_db, OPType.ANALYSE.value, 'open sleep analyse', 0)

            self.qlass_ui.clean_cache()  ##清理缓存
            # 计算原始数据的哈希值
            file_hash = self.qlass_ui.calculate_file_hash(self.file_path)
            self.file_hash = file_hash
            if file_hash:
                # 检查是否存在对应的缓存文件
                cached_results = self.qlass_ui.load_cache_by_hash(file_hash)
                if cached_results:
                    # 设置缓存按钮
                    self.qlass_ui.set_cached_results(cached_results)

        except Exception as e:
            QLLogging.log.exception(f"Error opening Qlass Analysis window: {str(e)}")
            print(f"Error opening Qlass Analysis window: {str(e)}")

    def create_close_handler(self):
        """创建一个闭包来处理关闭事件"""

        def handle_close(event):
            QLLogging.log.info("Qlass Analysis window closing...")
            self.close_qlass_analysis(event)
            QLLogging.log.info("Select Analysis window closing...")
            self.close_select_analysis(event)
            QLLogging.log.info("Rejection Analysis window closing...")
            self.close_reject_analysis(event)
            QLLogging.log.info("Epilepsy Analysis window closing...")
            self.close_epilepsy_analysis(event)
            QLLogging.log.info("Filter Analysis window closing...")
            self.close_filter(event)

        return handle_close

    def close_qlass_analysis(self, event=None):
        """关闭睡眠分析窗口并清理所有相关资源"""
        import matplotlib.pyplot as plt
        try:
            # 保存分析结果到缓存
            # if hasattr(self.qlass_ui, 'df_score') and self.qlass_ui.df_score is not None:
            #     self.qlass_ui.save_cache(self.file_hash)

            QLLogging.log.info("Starting Qlass Analysis cleanup...")
            if hasattr(self, 'qlass_ui') and self.qlass_ui is not None:
                # 先处理线程
                if hasattr(self.qlass_ui, 'thread_run'):
                    thread = self.qlass_ui.thread_run
                    if thread.isRunning():
                        thread.terminate()
                        thread.wait()
                    thread.cleanup()  # 调用新的cleanup方法
                    thread.deleteLater()  # 确保线程被正确删除

                # 清理matplotlib资源
                if hasattr(self.qlass_ui, 'figure'):
                    plt.close(self.qlass_ui.figure)
                    self.qlass_ui.figure.clear()
                    del self.qlass_ui.figure

                if hasattr(self.qlass_ui, 'canvas'):
                    self.qlass_ui.canvas.close()
                    del self.qlass_ui.canvas

                # 清理所有大型数据属性
                large_data_attrs = [
                    'raw_processed', 'df_score', 'eeg_data', 'emg_data',
                    'acc_data', 'spectrogram_data', 'scores', 'stages',
                    'color_epochs', 'highlight_lines', 'epochlabels'
                ]

                for attr in large_data_attrs:
                    if hasattr(self.qlass_ui, attr):
                        delattr(self.qlass_ui, attr)

                # 断开所有信号连接
                try:
                    self.qlass_ui.thread_run.signal.disconnect()
                except:
                    pass

                # 删除UI对象
                self.qlass_ui.deleteLater()
                self.qlass_ui = None

            # 关闭并删除窗口
            if self.qlass_window is not None:
                self.qlass_window.close()
                self.qlass_window = None

            # 强制多次垃圾回收
            import gc
            gc.collect()
            gc.collect()

            # 打印内存使用情况
            import psutil
            process = psutil.Process()
            QLLogging.log.info(f"Memory usage after closing Qlass Analysis: {process.memory_info().rss / 1024 / 1024:.2f} MB")

        except Exception as e:
            QLLogging.log.exception(f"Error during Qlass Analysis cleanup: {str(e)}")
            import traceback
            traceback.print_exc()
        finally:
            if event:
                event.accept()

