    def close_file(self):
        # 设置标志为：False
        self.is_not_first_open = False

        # 成功加载数据后启用菜单和关闭
        self.menuPreprocess.setEnabled(False)
        self.menuAnalysis_module.setEnabled(False)
        self.action_close_file.setEnabled(False)
        self.action_save_file.setEnabled(False)

        # 清理掉
        self.show_file_widget.hide()
        self.show_file_ScrollArea.hide()

        self.welcome_widget.welcome_text0.show()
        self.welcome_widget.welcome_widget_old.show()
        self.welcome_widget.welcome_text1.show()

        """关闭文件时清理所有打开的窗口和数据"""
        try:
            # 1. 关闭所有特殊窗口
            special_windows = [
                (self.qlass_window, self.close_qlass_analysis),
                (self.select_window, self.close_select_analysis),
                (self.reject_window, self.close_reject_analysis),
                (self.epilepsy_window, self.close_epilepsy_analysis),
                (self.filter_window, self.close_filter),
                (getattr(self, 'bandpower_ui', None), None),
                (getattr(self, 'PSD_ui', None), None),
                (getattr(self, 'time_frenquency_ui', None), None),
                (getattr(self, 'activity_ui', None), None),
                (getattr(self, 'EMG_window', None), None),
                (getattr(self, 'ECG_window', None), None),
                (getattr(self, 'recommand_window', None), None),
            ]

            for window, close_func in special_windows:
                if window is not None:
                    if close_func:
                        close_func()
                    else:
                        window.close()
                        # 获取窗口的属性名并安全地删除
                        window_name = window.objectName()
                        if window_name and hasattr(self, window_name):
                            delattr(self, window_name)

            # 2. 清理UI对象
            ui_attributes = [
                'qlass_ui', 'filter_ui', 'select_ui', 'reject_ui',
                'basical_ui', 'EMG_ui', 'ECG_ui', 'epilepsy_ui'
            ]

            for attr in ui_attributes:
                if hasattr(self, attr):
                    ui_obj = getattr(self, attr)
                    if hasattr(ui_obj, 'closeEvent'):
                        ui_obj.closeEvent(QtCore.QEvent(QtCore.QEvent.Close))
                    if hasattr(ui_obj, 'raw_processed'):
                        del ui_obj.raw_processed
                    delattr(self, attr)

            # 3. 清理数据对象
            data_objects = ['raw', 'raw_processed', 'file_path', 'info_text', 'info_text2']
            for obj in data_objects:
                if hasattr(self, obj):
                    delattr(self, obj)

            # 4. 重置UI状态
            # self.textEdit.clear()
            self.show_file_ScrollArea.hide()
            self.menuPreprocess.setEnabled(False)
            self.menuAnalysis_module.setEnabled(False)
            self.action_close_file.setEnabled(False)
            self.action_save_file.setEnabled(False)
            self.statusbar.showMessage("File closed and memory cleared", 2000)

            # 5. 强制垃圾回收
            import gc
            gc.collect()
            gc.collect()

            # 6. 打印内存使用情况（调试用）
            import psutil
            process = psutil.Process()
            print(f"Memory usage after cleanup: {process.memory_info().rss / 1024 / 1024:.2f} MB")
            QLLogging.log.debug(f"Memory usage after cleanup: {process.memory_info().rss / 1024 / 1024:.2f} MB")

            # 7. 清理存储的历史数据
            self.history_filter_log = [[] for _ in range(7)]
            self.history_reject_time = []

        except Exception as e:
            QLLogging.log.debug(f"Error during cleanup: {str(e)}")
            import traceback
            traceback.print_exc()

    def exit_application(self):
        """退出应用程序"""
        reply = QtWidgets.QMessageBox.question(
            None,
            'Exit',
            'Are you sure you want to exit?',
            QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No,
            QtWidgets.QMessageBox.No
        )

        if reply == QtWidgets.QMessageBox.Yes:
            # 确保关闭睡眠分期窗口
            if self.qlass_window is not None:
                self.close_qlass_analysis()
            # 确保关闭选择窗口
            if self.select_window is not None:
                self.close_select_analysis()
            # 确保关闭坏段拒绝窗口
            if self.reject_window is not None:
                self.close_reject_analysis()
            # 确保关闭癫痫窗口
            if self.reject_window is not None:
                self.close_epilepsy_analysis()
            if self.filter_window is not None:
                self.close_filter()

            # 关闭所有窗口
            for window, ui in self.windows:
                window.close()

            # 清理资源
            self.windows.clear()
            if hasattr(self, 'raw'):
                del self.raw
            if hasattr(self, 'raw_processed'):
                del self.raw_processed

            # 强制垃圾回收
            import gc
            gc.collect()

            QtWidgets.QApplication.quit()

